const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto');
const root=path.resolve(__dirname,'..'),copy=require('../data/buyer-clarity-20261027'),changed=new Set();
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const plain=s=>s.replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;|&apos;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&nbsp;/g,'\u00a0').replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(+n)).trim();
const localePath=(locale,p)=>(locale==='en'?'':'/'+locale)+p;
function meta(h,title,description,h1){
 if(title){h=h.replace(/<title>[\s\S]*?<\/title>/,'<title>'+esc(title)+'</title>');h=h.replace(/(<meta (?:property|name)="(?:og:title|twitter:title)" content=")[^"]*"/g,'$1'+esc(title)+'"');}
 if(description)h=h.replace(/(<meta (?:name|property)="(?:description|og:description|twitter:description)" content=")[^"]*"/g,'$1'+esc(description)+'"');
 if(h1)h=h.replace(/<h1>[\s\S]*?<\/h1>/,'<h1>'+esc(h1)+'</h1>');return h;
}
function answer(h,text){assert(/<p class="answer">[\s\S]*?<\/p>/.test(h));return h.replace(/<p class="answer">[\s\S]*?<\/p>/,'<p class="answer">'+esc(text)+'</p>');}
function section(h,id,title,body,before='frequently-asked-questions'){
 body=body.replaceAll('<div class="table-wrap">','<div class="table-wrap" role="region" aria-label="'+esc(title)+'" tabindex="0">').replaceAll('<th>','<th scope="col">');
 assert(!h.includes('id="'+id+'"'));const re=new RegExp('<section\\b[^>]*\\bid="'+before+'"[^>]*>');assert(re.test(h),'missing insertion section '+before);
 h=h.replace(re,'<section class="competitive-depth" id="'+id+'"><h2>'+esc(title)+'</h2>'+body+'</section>\n$&');
 let n=0;h=h.replace(/<a href="#frequently-asked-questions">/g,()=>{n++;return '<a href="#'+id+'">'+esc(title)+'</a><a href="#frequently-asked-questions">';});assert(n>=2,'both reading navigators must receive section');return h;
}
function updateGraph(h){
 const visible=[...h.matchAll(/<details[^>]*>\s*<summary[^>]*>([^<]+)<\/summary>\s*<p>([\s\S]*?)<\/p>\s*<\/details>/g)].map(m=>({q:plain(m[1]),a:plain(m[2])}));
 return h.replace(/(<script type="application\/ld\+json">)([\s\S]*?)(<\/script>)/g,(_,a,raw,z)=>{const d=JSON.parse(raw),nodes=d['@graph']||[d];for(const n of nodes){if(n['@type']==='FAQPage'){assert.equal(n.mainEntity.length,visible.length,'FAQ count');for(const [i,q] of n.mainEntity.entries()){assert.equal(q.name,visible[i].q,'FAQ question parity');q.acceptedAnswer.text=visible[i].a;}}
 if(['WebPage','Article'].includes(n['@type'])){if(n.dateModified)n.dateModified='2026-10-27T00:00:00+00:00';if(n.headline)n.headline=plain(h.match(/<h1>([\s\S]*?)<\/h1>/)[1]);if(n.name)n.name=plain(h.match(/<h1>([\s\S]*?)<\/h1>/)[1]);if(n.description)n.description=plain(h.match(/<meta name="description" content="([^"]*)"/)[1]);}}
 return a+JSON.stringify(d)+z;});
}
function edit(p,locale,fn){const file=path.join(root,p.slice(1),'index.html');let h=fs.readFileSync(file,'utf8'),old=h;h=fn(h);if(h===old)return;h=updateGraph(h);const dates={en:'Updated October 27, 2026',es:'Actualizado el 27 de octubre de 2026',ca:'Actualitzat el 27 d’octubre de 2026',fr:'Mis à jour le 27 octobre 2026'};h=h.replace(/Updated October \d{1,2}, 2026|Actualizado el \d{1,2} de octubre de 2026|Actualitzat el \d{1,2} d[’']octubre de 2026|Mis à jour le \d{1,2} octobre 2026/g,dates[locale]);fs.writeFileSync(file,h);changed.add(p);}
for(const locale of ['en','es','ca','fr']){
 edit(localePath(locale,'/services/linkedin-lead-generation/'),locale,h=>{
 h=answer(h,copy.linkedinAnswers[locale]);
 if(locale==='en'){
 h=meta(h,'LinkedIn Outreach Agency for B2B Lead Generation | Beespoke','Founder-led LinkedIn outreach for B2B teams. Compare scope, responsibilities, qualification and current terms before booking a fit call.','LinkedIn outreach agency for targeted B2B conversations');
 h=section(h,'linkedin-campaign-brief','From the campaign brief to a qualified meeting',`<p>Agree the buying hypothesis and responsibilities before comparing activity targets. A useful brief names the offer, target accounts, relevant buying roles, exclusions, approved evidence and the conditions for a suitable meeting.</p><div class="table-wrap"><table><caption>A reviewable division of work for a managed LinkedIn campaign</caption><thead><tr><th>Stage</th><th>Campaign work</th><th>Client decision or retained work</th></tr></thead><tbody><tr><td>Market and account selection</td><td>Research accounts, buying roles and the reason for contact</td><td>Confirm the offer, fit, exclusions and permitted evidence</td></tr><tr><td>Messages and follow-up</td><td>Prepare relevant outreach and follow-up within the agreed channel scope</td><td>Approve factual claims, account access and brand boundaries</td></tr><tr><td>Replies and qualification</td><td>Handle first replies and assess interest against agreed criteria</td><td>Supply expert answers and decide unresolved commercial exceptions</td></tr><tr><td>Meeting handoff</td><td>Book a suitable conversation and pass the context to the client</td><td>Lead discovery, proposals, negotiation and closing</td></tr></tbody></table></div><h3>A fictional brief, not a client result</h3><p>An industrial maintenance software provider wants to test one buyer segment. Its operations lead confirms the account criteria and excludes current customers; the campaign brief names the likely buyer, a relevant operational question and the evidence permitted in messages. A meeting is suitable only when the agreed account, role and interest criteria are met. A reply, a booking and a held qualified meeting are recorded separately. This example illustrates the decision process; it supplies no performance prediction.</p><p><a href="/resources/account-research-handoff-example/">Inspect the fictional research-to-handoff example</a> and <a href="/downloads/beespoke-icp-scorecard/">prepare the ICP and outreach worksheet</a>. If the problem is unclear, use the <a href="/guides/b2b-lead-generation-audit/">lead-generation audit guide</a> before selecting a campaign.</p><p>The <a href="/case-studies/cybersecurity-linkedin-lead-generation/">existing public cybersecurity case</a> describes one LinkedIn engagement. Its market, period and results do not predict another campaign. Use the original case to assess the research and qualification approach.</p><p>${esc(copy.terms.en)}</p>`);
 }return h;});
 edit(localePath(locale,'/guides/best-linkedin-lead-generation-agencies/'),locale,h=>{
 let count=0;h=h.replace(/(<details[^>]*>\s*<summary[^>]*>[^<]+<\/summary>\s*<p>)([\s\S]*?)(<\/p>\s*<\/details>)/g,(all,a,body,z)=>++count===2?a+esc(copy.priceAnswers[locale])+z:all);assert.equal(count,4);
 if(locale==='en')h=section(h,'from-shortlist-to-scope','From an agency shortlist to a written campaign scope',`<p>Use this guide to evaluate providers; use the <a href="/services/linkedin-lead-generation/">Beespoke LinkedIn outreach service</a> to decide whether its particular managed campaign fits. Keep the same requirements for every finalist, including Beespoke. Inclusion in this guide is not an independent endorsement.</p><ol><li>Write the target-account and buyer-role rules, the intended channel and any exclusions.</li><li>Ask who researches accounts, approves claims, handles replies and decides that a meeting is suitable.</li><li>Separate booked, held and qualified meetings. Ask for the period, denominator and original context behind any result.</li><li>Document client approvals, software/data costs, account access, ownership and handoff responsibilities before comparing fees.</li></ol><p>A narrow managed campaign, software assistance and a dedicated SDR team transfer different work. If your team cannot yet identify the constraint, start with the <a href="/guides/b2b-lead-generation-audit/">B2B lead-generation audit</a>. If your requirements are ready, review <a href="/services/linkedin-lead-generation/#linkedin-campaign-brief">the campaign brief and responsibilities</a>.</p>`);
 return h;});
 edit(localePath(locale,'/services/outsourced-sdr/'),locale,h=>{
 const marker={en:'Beespoke offers a managed LinkedIn campaign',es:'Beespoke ofrece una campaña de LinkedIn gestionada',ca:'Beespoke ofereix una campanya de LinkedIn gestionada',fr:'Beespoke propose une campagne LinkedIn gérée'}[locale];
 const newMarker={en:'Beespoke offers a managed cold email and/or LinkedIn campaign',es:'Beespoke ofrece una campaña gestionada de cold email y/o prospección por LinkedIn',ca:'Beespoke ofereix una campanya gestionada de cold email i/o prospecció per LinkedIn',fr:'Beespoke propose une campagne gérée de cold email et/ou de prospection sur LinkedIn'}[locale];
 h=h.replaceAll(marker,newMarker);
 if(locale==='fr'){
 h=meta(h,'SDR externalisé : prospection B2B email et LinkedIn | Beespoke','Un SDR externalisé sous forme de campagne gérée : périmètre, responsabilités, brief et tarifs. Email et/ou LinkedIn ; appels sur devis.','SDR externalisé : une campagne de prospection B2B gérée');
 const corrections={'Audit de la portée originale':'Vérification du périmètre initial','Personnes nommées et propriétaire de la direction':'Intervenants identifiés et responsable côté client','Capacité hebdomadaire exacte':'Capacité hebdomadaire convenue','Propriété ICP, liste et message':'Responsabilité du ciblage, des listes et des messages','Workflow de réponse et de qualification':'Traitement des réponses et critères de qualification','Plan de rampe, de remplacement et de sortie':'Démarrage progressif, continuité et conditions de sortie','avant de comparer les mandats':'avant de comparer les prestations'};
 for(const [a,b] of Object.entries(corrections))h=h.replaceAll(a,b);
 h=section(h,'brief-sdr-externalise','Préparer un brief de prospection exploitable',`<p>Le choix du modèle ne remplace pas le brief. Reprenez la grille de périmètre existante et fournissez les éléments ci-dessous avant de comparer une campagne gérée, un commercial dédié et une équipe de prospection.</p><div class="table-wrap"><table><caption>Les décisions à clarifier entre votre équipe et le prestataire</caption><thead><tr><th>Élément du brief</th><th>Information utile</th><th>Décision côté client</th></tr></thead><tbody><tr><td>Offre et comptes ciblés</td><td>Problème résolu, profil d’entreprise, rôles d’achat et exclusions</td><td>Valider le marché et signaler les clients ou comptes à ne pas contacter</td></tr><tr><td>Messages et preuves</td><td>Hypothèse de pertinence, faits utilisables et limites de marque</td><td>Approuver les affirmations et fournir les réponses techniques</td></tr><tr><td>Qualification et transmission</td><td>Critères d’intérêt, contexte du rendez-vous et responsable de la suite</td><td>Mener la découverte, les propositions et la conclusion des ventes</td></tr><tr><td>Canaux et accès</td><td>Email et/ou LinkedIn convenus, outils, données et accès nécessaires</td><td>Confirmer le périmètre écrit ; chiffrer les appels séparément si nécessaire</td></tr></tbody></table></div><h3>Exemple fictif de brief : aucun résultat client revendiqué</h3><p>Un éditeur de logiciel de maintenance industrielle veut tester un seul segment. Il précise les entreprises visées, exclut ses clients actuels et indique qui traite les questions techniques. Le brief définit ce qui rend un rendez-vous pertinent et les informations à transmettre après une réponse. Réponse, rendez-vous réservé et rendez-vous qualifié tenu restent trois observations distinctes. Ce scénario explique la méthode de décision ; il ne prédit ni volume ni délai.</p><p>Consultez l’<a href="/fr/resources/account-research-handoff-example/">exemple fictif de recherche et de transmission</a> et la <a href="/fr/downloads/beespoke-icp-scorecard/">fiche de ciblage et de prospection</a>. Pour comparer l’économie du service, utilisez le <a href="/fr/guides/outbound-lead-generation-cost/">guide des tarifs de prospection</a>. Si le blocage reste inconnu, commencez par l’<a href="/fr/guides/b2b-lead-generation-audit/">audit de prospection B2B</a>.</p><p>L’<a href="/fr/case-studies/cybersecurity-linkedin-lead-generation/">étude de cas LinkedIn déjà publiée</a> conserve son marché et ses limites d’origine ; sa traduction ne démontre pas un résultat sur le marché français.</p>`);
 }return h;});
 edit(localePath(locale,'/guides/outbound-call-center-pricing/'),locale,h=>{
 const ending={en:'Beespoke’s standard service is LinkedIn-led, not a call center.',es:'El servicio estándar de Beespoke se centra en LinkedIn, no es un call center.',ca:'El servei estàndard de Beespoke se centra en LinkedIn, no és un call center.',fr:'Le service standard de Beespoke est centré sur LinkedIn, pas sur un centre d’appels.'}[locale];assert(h.includes(ending));h=h.replace(ending,esc(copy.scope[locale]));
 h=h.replace(/<p>([\s\S]*?)<\/p>/g,(all,t)=>{const x=plain(t);if(x.includes('Beespoke')&&x.includes('LinkedIn')&&(/call.center|centro de llamadas|centre de trucades|centre d.appels|téléphonique|telefónic|phone|trucades/i.test(x))&&!x.includes(copy.scope[locale])&&( /LinkedIn-focused|LinkedIn,|centrad[ao] en LinkedIn|centrada en LinkedIn|axée sur LinkedIn|centrée sur LinkedIn|centrat en LinkedIn|centrada en LinkedIn/.test(x)))return '<p>'+esc(copy.scope[locale])+'</p>';return all;});
 if(locale==='en'){const anchor='<section class="';const re=/(<section[^>]*id="call-center-quote-calculator"[^>]*>[\s\S]*?<h2>[\s\S]*?<\/h2>)/;assert(re.test(h));h=h.replace(re,'$1<p><strong>Before calculating:</strong> identify whether the proposal buys staffed calling hours, dedicated/shared capacity or software. The tool below compares two staffed-service billing models, not software seats. <a href="#start-by-naming-the-call-center-service">Check the service definitions first</a>, then enter the same currency, period and held-qualified-meeting criteria.</p>');}
 return h;});
}
edit('/compare/lead-generation-agency-vs-in-house-team/','en',h=>{
 h=meta(h,'Lead Generation Agency vs In-House: Costs, Control & Fit','Compare agency and in-house lead generation over the same scope and time period. Model your costs, retained work, ownership and handover.','Lead generation agency vs in-house: compare cost, control and fit');
 const fields=[['agencySetup','Agency setup or transition cost'],['agencyMonthly','Agency monthly fee'],['agencyTools','Agency-related tools/data per month'],['agencyOwner','Client management cost per month'],['internalHire','Internal recruiting/onboarding cost'],['internalMonthly','Internal monthly employment cost'],['internalTools','Internal tools/data per month'],['internalOwner','Internal coaching/management cost per month']];
 const inputs=fields.map(([key,label])=>`<p><label for="model-${key}">${label}</label><input id="model-${key}" name="${key}" data-model-input type="number" min="0" max="1000000000" step="any" inputmode="decimal"></p>`);
 const groupedInputs='<div class="buyer-cost-fields"><fieldset><legend>Managed campaign</legend>'+inputs.slice(0,4).join('')+'</fieldset><fieldset><legend>Internal operation</legend>'+inputs.slice(4).join('')+'</fieldset></div>';
 h=section(h,'same-scope-cost-model','Compare the same capability over 3, 6 and 12 months',`<p>Compare one defined operating job before its price. A managed campaign, one SDR and an entire marketing team are different capacities. Name the channels, research depth, reply work, client decisions and output definition for each option. Lower cost does not establish equal capacity or better results.</p><p>Use your actual quotes and internal employment costs. Include benefits in employment cost and onboarding/ramp expense in the one-time input; do not add the same expense twice. If monthly staffing or fees change during ramp, calculate each stage separately outside this constant-cost model. Time to first result and opportunity cost are not estimated here.</p><form data-buyer-model novalidate><p><label for="model-currency">One currency for both models</label><select id="model-currency" name="currency"><option>USD</option><option>EUR</option><option>GBP</option></select></p><p>Changing the currency label does not convert amounts. Blank means unknown; 0 means a cost is genuinely zero. Inputs stay in this page and are not saved or sent to Analytics.</p>${groupedInputs}<p><button type="submit">Compare my costs</button> <button type="reset">Clear inputs</button></p><p data-model-status role="status" aria-live="polite">Enter your own comparable quotes and costs. A blank is unknown; enter 0 only when the cost is genuinely zero.</p><div class="table-wrap" role="region" aria-label="Your input-based cost comparison" tabindex="0" data-model-output hidden></div></form><p>Without JavaScript: total cost = one-time cost + months × (monthly execution/employment cost + tools/data + client management). Compare 3, 6 and 12 months using the same scope and currency. This is cost arithmetic, not a meeting, revenue or hiring-speed forecast.</p><p>For a software-versus-managed-execution choice, use the existing <a href="/compare/lead-generation-agency-vs-software/">software-versus-agency cost comparison</a>. For an uncertain acquisition constraint, use the <a href="/guides/b2b-lead-generation-audit/">audit guide</a> before choosing capacity.</p>`);
 h=section(h,'handover-acceptance','Turn the handover list into acceptance criteria',`<p>Use the existing handover principles to review a concrete transfer. Complete this worksheet with your own criteria; nothing entered is saved. A blank is an unresolved decision, not an accepted handoff.</p><div class="table-wrap"><table><caption>Agency, internal and hybrid handover acceptance</caption><thead><tr><th>Decision</th><th>Acceptance evidence to agree</th></tr></thead><tbody><tr><td>Equivalent operating scope</td><td>Same segment, channel, included tasks and retained client work</td></tr><tr><td>Targeting and suppression</td><td>Reviewed account rules, exclusions and one owner for each open conversation</td></tr><tr><td>Messages and evidence</td><td>Approved claims, versions and permission to reuse the underlying material</td></tr><tr><td>Qualification</td><td>Separate booked, held, qualified and opportunity definitions with the same cohort</td></tr><tr><td>Access and records</td><td>Agreed account/data ownership, exportability, access removal and retention responsibilities</td></tr><tr><td>Review and exit</td><td>Named owner, review date and explicit unresolved items before acceptance</td></tr></tbody></table></div><p><label for="handover-notes">Your scope, acceptance evidence and unresolved decisions</label><textarea id="handover-notes" rows="5" placeholder="Record only the working notes you need; avoid personal or confidential data."></textarea></p><p>Copy notes to your own approved workspace before leaving this page; they are not retained here. Compare the actual <a href="/services/outbound-lead-generation/">managed outbound scope</a> when that model fits. A hybrid setup also needs a clear owner for every buyer conversation.</p>`);
 const v=crypto.createHash('sha256').update(fs.readFileSync(path.join(root,'buyer-model.js'))).digest('hex').slice(0,12);const cssVersion=crypto.createHash('sha256').update(fs.readFileSync(path.join(root,'buyer-model.css'))).digest('hex').slice(0,12);return h.replace('</head>','<link rel="stylesheet" href="/buyer-model.css?v='+cssVersion+'"></head>').replace('</body>','<script src="/buyer-model.js?v='+v+'" defer></script></body>');
});
edit('/fr/guides/outbound-lead-generation-cost/','fr',h=>{
 const old=plain(h.match(/<p class="answer">([\s\S]*?)<\/p>/)[1]).replace('offres publiques actuelles','offres publiques observées');
 h=meta(h,'Tarifs d’une agence de prospection B2B : budget et périmètre','Comparez les tarifs de prospection B2B : périmètre, coûts annexes et rendez-vous qualifiés. Distinguez les observations historiques du forfait actuel.','Tarifs d’une agence de prospection B2B : comparer le budget et le périmètre');
 h=answer(h,'Les agences de prospection B2B peuvent facturer un forfait mensuel, des rendez-vous ou un modèle hybride. Comparez le même périmètre, les outils, les données, le temps client et les critères de qualification. Chez Beespoke, le forfait cold email et/ou LinkedIn est de 1 500 EUR par mois en Europe, avec un engagement minimum de trois mois ; les coûts de tiers sont séparés et les appels font l’objet d’un devis distinct. Le benchmark de juillet 2026 reste une observation historique.');
 h=section(h,'tarifs-actuels-et-benchmark','Distinguer le forfait actuel du benchmark historique',`<p>${esc(copy.terms.fr)}</p><p>${esc(old)}</p><p>Ces observations datées ne constituent ni un tarif actuel garanti chez ces prestataires ni une moyenne du marché. Les devis peuvent couvrir des logiciels, des capacités et des tâches différents ; conservez leurs devises et leurs dates d’origine. La question d’un budget de 10 000 USD reste utile pour juger un périmètre particulier, sans représenter le tarif standard de Beespoke.</p><p>Pour choisir le modèle de prestation, consultez le <a href="/fr/services/outsourced-sdr/">service de SDR externalisé</a> et son brief. Pour comprendre l’offre de campagne, consultez le <a href="/fr/services/outbound-lead-generation/">service de prospection outbound</a>. Si vous ne savez pas quel maillon limite les rendez-vous, utilisez l’<a href="/fr/guides/b2b-lead-generation-audit/">audit de prospection B2B</a>.</p>`);return h.replaceAll('offres publiques actuelles','offres publiques observées');
});
